export default function({$,$$,K,html,raw,put,S,TRIPS,TOWNS,opts}){const P={booking(){$('#back').onclick=e=>{e.preventDefault();history.back()};const t=TRIPS.find(x=>x.id==new URLSearchParams(location.search).get('trip'))||TRIPS[0],q=S.get('q',{f:'Lusaka',t:'Kitwe',pax:2,d:'2026-10-24'});const taken=[3,4,9,10,11,15,16,20];let sel=[],nm={};$('#tinfo').textContent=`${t.op} · ${q.f} → ${q.t} · ${q.d} · ${t.dep}`;let h=[];for(let i=1;i<=24;i++){const x=taken.includes(i);h.push(html`<button type="button" class="seat${x?' t':''}" data-n="${i}" aria-label="Seat ${i}${x?', booked':''}"${x?' disabled':''}>${i}</button>`);if(i%4==2)h.push(html`<span class="gap"></span>`)}put($('#seats'),h);const draw=()=>{$$('.seat').forEach(b=>b.classList.toggle('s',sel.includes(+b.dataset.n)));put($('#pf'),sel.map((n,i)=>html`<fieldset class="card"><legend>Passenger ${i+1} · Seat ${n}</legend><label>Full name (as on ID)</label><input class="in pn" data-n="${n}" value="${nm[n]||''}" required><label>NRC or passport number (optional)</label><input class="in"></fieldset>`));$$('.pn').forEach(e=>e.oninput=()=>nm[e.dataset.n]=e.value);$('#ssum').textContent=sel.length?`${sel.length} of ${q.pax} seats: ${sel.join(', ')}`:`Select ${q.pax} seat${q.pax>1?'s':''}`;$('#fare').textContent=K(sel.length*t.fare);$('#total').textContent=K(sel.length*t.fare+(sel.length?20:0))};$('#seats').onclick=e=>{const n=+e.target.dataset.n;if(!n)return;if(sel.includes(n))sel=sel.filter(x=>x!=n);else if(sel.length<q.pax)sel.push(n);else $('#msg').textContent=`You are booking for ${q.pax}. Unselect a seat first.`;draw()};$('#go').onclick=()=>{const em=$('#email').value,ph=$('#phone').value;if(sel.length!=q.pax||!em||!ph||sel.some(n=>!nm[n])){$('#msg').textContent='Select all seats, enter every passenger name, and add your phone and email.';return}
S.set('order',{trip:t,q,seats:sel,names:sel.map(n=>nm[n]),total:sel.length*t.fare+20,email:em,phone:ph});location='checkout.html'}
draw()}
};return P.booking;}